"""Bundled JSON Schemas generated by scripts/generate-contracts.py (do not edit)."""

from __future__ import annotations

import json
from functools import cache
from importlib import resources
from typing import Any

from jsonschema import Draft202012Validator

SCHEMA_VERSION = "1.0"


@cache
def load_schema(name: str) -> dict[str, Any]:
    text = resources.files(__package__).joinpath(f"{name}.schema.json").read_text("utf-8")
    schema = json.loads(text)
    Draft202012Validator.check_schema(schema)
    return schema


@cache
def scene_validator() -> Draft202012Validator:
    return Draft202012Validator(load_schema("scene"))


@cache
def layout_validator() -> Draft202012Validator:
    return Draft202012Validator(load_schema("layout"))
